<script setup lang="ts">
import {ref,onMounted} from 'vue';
import type {Bank,BankMember,Page,LibraryQuestionSummary,ResourceReceipt} from '@survey/shared';
import {api} from '../api';
import {queryPage,useOperation} from '../library-client';
const banks=ref<Bank[]>([]),cursor=ref<string|null>(null),selected=ref<Bank|null>(null),members=ref<BankMember[]>([]),memberCursor=ref<string|null>(null),name=ref(''),rename=ref(''),scope=ref('own'),questions=ref<LibraryQuestionSummary[]>([]),questionCursor=ref<string|null>(null),questionId=ref(''),busy=ref(false),error=ref(''),notice=ref(''),op=useOperation();
async function load(more=false){busy.value=true;error.value='';try{const p=await api<Page<Bank>>('/question-banks'+queryPage({limit:'20',cursor:more?cursor.value??undefined:undefined}));banks.value=more?[...banks.value,...p.items]:p.items;cursor.value=p.nextCursor;if(selected.value){const actual=banks.value.find(b=>b.id===selected.value!.id);if(actual)selected.value=actual;}}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function create(){busy.value=true;error.value='';try{const r=await op.run<ResourceReceipt>('/question-banks',{name:name.value});name.value='';await load();const b=banks.value.find(x=>x.id===r.resourceId);if(b)await select(b);notice.value='题库已创建。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function select(b:Bank){selected.value=b;rename.value=b.name;await loadMembers();}
async function loadMembers(more=false){if(!selected.value)return;busy.value=true;error.value='';try{const p=await api<Page<BankMember>>(`/question-banks/${selected.value.id}/members`+queryPage({limit:'20',cursor:more?memberCursor.value??undefined:undefined}));members.value=more?[...members.value,...p.items]:p.items;memberCursor.value=p.nextCursor;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function chooseQuestions(more=false){busy.value=true;try{const p=await api<Page<LibraryQuestionSummary>>('/questions'+queryPage({scope:scope.value,limit:'20',cursor:more?questionCursor.value??undefined:undefined}));questions.value=more?[...questions.value,...p.items]:p.items;questionCursor.value=p.nextCursor;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function change(action:'rename'|'delete'|'add'|'remove',qid?:string){
 if(!selected.value||op.pending.value)return;if(action==='delete'&&!window.confirm('删除题库只删除整理目录，题目、版本和问卷引用都会保留。继续？'))return;
 busy.value=true;error.value='';notice.value='';const b=selected.value;
 try{
  if(action==='rename'){const actual=await api<Bank>(`/question-banks/${b.id}`,'PATCH',{expectedRevision:b.revision,name:rename.value});Object.assign(b,actual);}
  else if(action==='delete'){await api(`/question-banks/${b.id}/deletion`,'POST',{expectedRevision:b.revision});selected.value=null;members.value=[];await load();}
  else{const r=await api<{revision:number}>(`/question-banks/${b.id}/members/${qid??questionId.value}`,'PUT',{expectedRevision:b.revision,present:action==='add'});b.revision=r.revision;await loadMembers();}
  notice.value='题库整理已保存，题目身份与历史保持不变。';
 }catch(e){error.value=`${(e as Error).message}。请刷新题库列表后比较，名称输入仍保留。`;}
 finally{busy.value=false;}
}
onMounted(async()=>{await load();await chooseQuestions();});
</script>
<template><section class="library-page"><RouterLink class="back" to="/questions">← 返回题目工作台</RouterLink><h1 tabindex="-1">我的题库</h1><p class="muted">题库用于整理。同一道题加入多个库，仍共用一套身份与版本。</p><p v-if="error" class="error" role="alert">{{error}} <button class="quiet" @click="load()">刷新题库列表</button></p><p v-if="notice" class="saved" role="status">{{notice}}</p><p v-if="busy" role="status" aria-busy="true">正在保存或读取…</p><form class="panel library-create" @submit.prevent="create"><label for="new-bank-name">题库名称</label><input id="new-bank-name" v-model="name" :disabled="busy||!!op.pending.value||!!op.pending.value"><button class="primary" :disabled="busy||!!op.pending.value||!name.trim()">{{op.pending.value?'重试原创建':'创建题库'}}</button></form>
<div class="library-layout"><section class="panel"><h2>题库目录</h2><p v-if="!banks.length&&!busy">还没有题库。可先创建目录，再加入自己或有效共享的题目。</p><ul class="library-rows"><li v-for="b in banks" :key="b.id"><button class="quiet" :aria-pressed="selected?.id===b.id" :disabled="busy||!!op.pending.value||!!op.pending.value" @click="select(b)">{{b.name}}</button></li></ul><button v-if="cursor" class="secondary" :disabled="busy||!!op.pending.value||!!op.pending.value" @click="load(true)">更多题库</button></section>
<section v-if="selected" class="panel"><h2>{{selected.name}}</h2><form @submit.prevent="change('rename')"><label for="rename-bank">修改名称</label><input id="rename-bank" v-model="rename" :disabled="busy||!!op.pending.value"><div class="editor-actions"><button class="secondary" :disabled="busy||!!op.pending.value||!rename.trim()">保存名称</button><button type="button" class="quiet danger" :disabled="busy||!!op.pending.value||!!op.pending.value" @click="change('delete')">删除此题库</button></div></form><h3>加入题目</h3><label for="bank-question-scope">题目来源</label><select id="bank-question-scope" v-model="scope" :disabled="busy||!!op.pending.value" @change="chooseQuestions()"><option value="own">我的题目</option><option value="shared">共享给我</option></select><label for="bank-question">选择题目</label><select id="bank-question" v-model="questionId" :disabled="busy||!!op.pending.value"><option value="">请选择</option><option v-for="q in questions" :key="q.id" :value="q.id">{{q.title}}（{{q.latestVersion===null?'无正式版':`v${q.latestVersion}`}}）</option></select><div class="editor-actions"><button class="secondary" :disabled="busy||!!op.pending.value||!questionId" @click="change('add')">加入此题库</button><button v-if="questionCursor" class="quiet" :disabled="busy||!!op.pending.value||!!op.pending.value" @click="chooseQuestions(true)">更多可选题目</button></div><h3>库中题目</h3><p v-if="!members.length&&!busy">此题库还没有成员。</p><ul class="library-rows"><li v-for="m in members" :key="m.questionId"><RouterLink v-if="m.selectable" :to="`/questions/${m.questionId}${scope==='shared'?'?shared=1':''}`">{{m.title}} · v{{m.latestVersion}}</RouterLink><span v-else>当前不可选用（共享已失效或尚无正式版）</span><button class="quiet" :disabled="busy||!!op.pending.value||!!op.pending.value" @click="change('remove',m.questionId)">移出题库</button></li></ul><button v-if="memberCursor" class="secondary" :disabled="busy||!!op.pending.value||!!op.pending.value" @click="loadMembers(true)">更多成员</button></section><p v-else class="panel">选择一个题库，查看并整理其中题目。</p></div></section></template>
